"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[8155],{3331:(e,r,n)=>{n.d(r,{R:()=>a,x:()=>o});var i=n(36672);const t={},s=i.createContext(t);function a(e){const r=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),i.createElement(s.Provider,{value:r},e.children)}},30600:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>o,default:()=>m,frontMatter:()=>a,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"LLama-effekten: L\xe6kage udl\xf8ste en r\xe6kke open source-alternativer til ChatGPT","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/da/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10. april 2023","top_news":"LLama-effekten: L\xe6kage udl\xf8ste en r\xe6kke open source-alternativer til ChatGPT"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/da/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/da/2023/04/09"}}');var t=n(23420),s=n(3331);const a={localized_date:"10. april 2023",top_news:"LLama-effekten: L\xe6kage udl\xf8ste en r\xe6kke open source-alternativer til ChatGPT"},o="2023-04-10",l={},d=[{value:"LLama-effekten: L\xe6kage udl\xf8ste en r\xe6kke open source-alternativer til ChatGPT",id:"llama-effekten-l\xe6kage-udl\xf8ste-en-r\xe6kke-open-source-alternativer-til-chatgpt",level:2},{value:"Fra dyb til lang l\xe6ring?",id:"fra-dyb-til-lang-l\xe6ring",level:2},{value:"EY f\xe5r forbud mod nye revisionsforretninger i Tyskland",id:"ey-f\xe5r-forbud-mod-nye-revisionsforretninger-i-tyskland",level:2},{value:"Solnedgang p\xe5 Sydpolen",id:"solnedgang-p\xe5-sydpolen",level:2},{value:"Hollandsk journalist, der skriver kritisk om Kina, er m\xe5l for intimideringsplan",id:"hollandsk-journalist-der-skriver-kritisk-om-kina-er-m\xe5l-for-intimideringsplan",level:2},{value:"USPS-anl\xe6g i Utah g\xf8r intet andet end at tyde h\xe5ndskrift",id:"usps-anl\xe6g-i-utah-g\xf8r-intet-andet-end-at-tyde-h\xe5ndskrift",level:2},{value:"Apple forts\xe6tter bestr\xe6belserne p\xe5 at forhindre detailbutikker i at blive fagforenet",id:"apple-forts\xe6tter-bestr\xe6belserne-p\xe5-at-forhindre-detailbutikker-i-at-blive-fagforenet",level:2},{value:"PL/Rust 1.0: nu et p\xe5lideligt sprog til Postgres",id:"plrust-10-nu-et-p\xe5lideligt-sprog-til-postgres",level:2},{value:"Twitter blokerer likes og retweets, der n\xe6vner Substack",id:"twitter-blokerer-likes-og-retweets-der-n\xe6vner-substack",level:2},{value:"Z-Library vil lade brugerne dele fysiske b\xf8ger",id:"z-library-vil-lade-brugerne-dele-fysiske-b\xf8ger",level:2},{value:"Perseus - NextJS-alternativ i Rust",id:"perseus---nextjs-alternativ-i-rust",level:2},{value:"En baby GPT",id:"en-baby-gpt",level:2},{value:"To typer af softwareingeni\xf8rer",id:"to-typer-af-softwareingeni\xf8rer",level:2},{value:"Avanceret Linux-programmering (2001)",id:"avanceret-linux-programmering-2001",level:2},{value:"Et CERN for Open Source Large-Scale AI",id:"et-cern-for-open-source-large-scale-ai",level:2},{value:"Permafrost-motor - en OpenGL RTS-spilmotor skrevet i C",id:"permafrost-motor---en-opengl-rts-spilmotor-skrevet-i-c",level:2},{value:"Lukning af en for\xe6ldet SSH-forbindelse",id:"lukning-af-en-for\xe6ldet-ssh-forbindelse",level:2},{value:"Flatcar Container Linux",id:"flatcar-container-linux",level:2},{value:"Microsoft / JARVIS: et system til at forbinde LLM&#39;er med ML-f\xe6llesskabet",id:"microsoft--jarvis-et-system-til-at-forbinde-llmer-med-ml-f\xe6llesskabet",level:2},{value:"Sf\xe6risk tokamak opn\xe5r afg\xf8rende plasmatemperaturer",id:"sf\xe6risk-tokamak-opn\xe5r-afg\xf8rende-plasmatemperaturer",level:2},{value:"De f\xf8rste &quot;p\xe5ske\xe6g&quot; i et spil var et opr\xf8r fra virksomhedernes side",id:"de-f\xf8rste-p\xe5ske\xe6g-i-et-spil-var-et-opr\xf8r-fra-virksomhedernes-side",level:2},{value:"Modular Fejl i Rust",id:"modular-fejl-i-rust",level:2},{value:"68-95-99.7 Regel",id:"68-95-997-regel",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Digitale samlerobjekter p\xe5 Instagram er ved at blive afviklet",id:"digitale-samlerobjekter-p\xe5-instagram-er-ved-at-blive-afviklet",level:2},{value:"Den afg\xf8relse, der truer bibliotekernes fremtid",id:"den-afg\xf8relse-der-truer-bibliotekernes-fremtid",level:2},{value:"Do Kwon konverterede ulovlige midler fra LUNA til Bitcoin",id:"do-kwon-konverterede-ulovlige-midler-fra-luna-til-bitcoin",level:2},{value:"Interview med Andrew Kelley (Zig Creator) (2021)",id:"interview-med-andrew-kelley-zig-creator-2021",level:2},{value:"Supavisor - en Postgres connection pooler skrevet i Elixir",id:"supavisor---en-postgres-connection-pooler-skrevet-i-elixir",level:2},{value:"Nye beskyldninger om plagiat mod Roy Lichtenstein",id:"nye-beskyldninger-om-plagiat-mod-roy-lichtenstein",level:2}];function g(e){const r={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,t.jsx)(r.h2,{id:"llama-effekten-l\xe6kage-udl\xf8ste-en-r\xe6kke-open-source-alternativer-til-chatgpt",children:"LLama-effekten: L\xe6kage udl\xf8ste en r\xe6kke open source-alternativer til ChatGPT"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Original"}),'.\nDen utilsigtede l\xe6kage af "Llama", en LLM-model, har udl\xf8st en alternativ bev\xe6gelse med \xe5ben kildekode til modeller som GPT-4 og Cohere, der kun er tilg\xe6ngelige via API\'er. Siden l\xe6kagen er bl.a. Alpaca, Vicuna, Koala, ColossalChat og ChatLLama blevet frigivet, som alle er bygget p\xe5 Llama. Open source-alternativerne til disse modeller har ikke vist samme pr\xe6stationsniveau f\xf8r Llama-udgivelsen. L\xe6kket af Llama har vist sig at v\xe6re en af de st\xf8rste gnister af innovation inden for open source LLM-omr\xe5det, hvor en krig mellem open source og API-baseret distribution truer. LLama-effekten har bevist, at open source er en levedygtig distributionsmekanisme for grundl\xe6ggende modeller, og der er nogle interessante kilder til innovation inden for LLM-omr\xe5det.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),".\n'The LLama Effect'-l\xe6kagen har udl\xf8st open source-alternativer til ChatGPT, hvilket har vakt opm\xe6rksomhed blandt teknologieksperter. GPT-4 demonstrerer mere betydelig intelligens og tilbyder r\xe6sonnement og generaliserende evner fra sin forg\xe6nger, GPT-3. AI-tekstmodeller forst\xe5r rumlige r\xe6sonnementer og kan forst\xe5 puslespil, men manuel finjustering er n\xf8dvendig. Der er debat om sprogmodellernes faktiske indl\xe6ringsniveau, der sker, med h\xe5b om en tilg\xe6ngelig og demokratiseret AI-fremtid. LLaMA-l\xe6kagen har f\xf8rt til open source-optimering p\xe5 alle platforme; eksperter kritiserer dog softwarepirateri og AI-virksomheders regulering. OpenAI kan st\xe5 over for juridiske udfordringer for at bruge modeller til at tr\xe6ne kommercielle resultater. ChatGPT-pr\xe6cisionen er divergerende, idet nogle anser den for ubrugelig, mens andre h\xe6vder, at GPT-4 forbedrer p\xe5 nogle omr\xe5der. Bing/Sydney og ChatGPT har forskellige personligheder. Indl\xe6gget giver ikke nye teknologiske fakta, men diskuterer karakteren af tekstkomprimering."]}),"\n",(0,t.jsx)(r.h2,{id:"fra-dyb-til-lang-l\xe6ring",children:"Fra dyb til lang l\xe6ring?"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Original"}),".\nStanford-forskere fra Hazy Research lab forbedrer sekvensl\xe6ngden i modeller for maskinl\xe6ringsfundamenter med fokus p\xe5 at skabe n\xe6sten line\xe6re tidsmodeller i sekvensl\xe6ngden, der kan f\xf8re til kontekstl\xe6ngder p\xe5 millioner eller endog milliarder. Hyena-modellen har skalerbarhed i sekvensl\xe6ngde op til 2k ved hj\xe6lp af et lille neuralt netv\xe6rk, der parametriserer de konvolutionelle filtre implicit via et andet lille neuralt netv\xe6rk med en implementeringstid p\xe5 O(NlogN). Forskere udforsker l\xe6ringsmatricer og deres forbindelse til sproglige applikationer. N/A."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nStanford-forskere unders\xf8ger omkostningsreduktion for selvopm\xe6rksomhed i lange sekvenser. Optimering af beregning til GPU'er og co-processorer kan optimere LLM'er. Skepsis omkring modeller med l\xe6ngere kontekst, kobling af LLM'er med andre systemer kan skabe nye l\xf8sninger. GPT-4-frigivelse f\xf8rer til ny forskning i forudsigelse af n\xe6ste token, potentielle gennembrud inden for associativ langtidshukommelse. Forst\xe5else af K,Q,V-repr\xe6sentation er afg\xf8rende, mens RNN'er og transformatorer har betydning for demokratisering af kunstig intelligens. L\xe6ngere kontekstl\xe6ngder kan betragtes som en ny form for s\xf8gning."]}),"\n",(0,t.jsx)(r.h2,{id:"ey-f\xe5r-forbud-mod-nye-revisionsforretninger-i-tyskland",children:"EY f\xe5r forbud mod nye revisionsforretninger i Tyskland"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Original"}),".\nEY er blevet forbudt i to \xe5r mod at revidere nye b\xf8rsnoterede kunder i Tyskland, da APAS, Tysklands tilsynsmyndighed for regnskabsv\xe6senet, har udstedt en b\xf8de p\xe5 500.000 EUR sammen med den strengeste straf nogensinde. Beslutningen, der kommer efter en tre\xe5rig unders\xf8gelse af EY's rolle i Wirecard-skandalen, har p\xe5f\xf8rt den kriseramte revisionsgigant et betydeligt \xf8konomisk og omd\xf8mmepolitisk slag. EY havde givet Wirecard en ren straffeattest, indtil selskabet kollapsede i 2020 p\xe5 grund af beskyldninger om massiv \xf8konomisk svindel. Efter Wirecard-skandalen har EY angiveligt op til 2 mia. dollar over tre \xe5r for at forbedre revisioner vedr\xf8rende teknologi og afsl\xf8ring af svig, men ingen revisor vil sandsynligvis g\xf8re tingene rigtigt hver gang."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),'.\nErnst & Young (EY) har f\xe5et forbud mod at udf\xf8re nye revisioner i Tyskland p\xe5 grund af ukorrekte revisionsbeslutninger og indblanding i Wirecard-skandalen. Konsulentfirmaer udliciterer lavere betalt personale for at minimere risikoen, men dette kan give bagslag. Revisorer giver kun en rimelig sikkerhed og garanterer ikke, at der ikke vil ske svig. Brug af automatisering og AI kan hj\xe6lpe med at opdage svigagtige aktiviteter. Revision b\xf8r adskilles fra r\xe5dgivning for at undg\xe5 interessekonflikter. Der er debat om v\xe6rdien af konsulentfirmaer og behovet for "skin in the game".']}),"\n",(0,t.jsx)(r.h2,{id:"solnedgang-p\xe5-sydpolen",children:"Solnedgang p\xe5 Sydpolen"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://brr.fyi/posts/sunset",children:"Original"}),'.\nP\xe5 sydpolstationen roterer solen i en n\xe6sten perfekt cirkel mod uret rundt p\xe5 himlen, s\xe5 der ikke er forskel p\xe5 "nat" og "dag". Som f\xf8lge heraf er solnedgangen spredt ud over flere uger, og temperaturen falder hurtigt, n\xe5r solen st\xe5r lavt p\xe5 himlen, normalt omkring midten af februar. Indl\xe6gget indeholder fotografier af solnedgangsbilleder fra forskellige retninger samt en video til at demonstrere det m\xe6rkelige f\xe6nomen. Stationen overholder ogs\xe5 "sommertid", selv om der ikke er nogen synlig forskel mellem tiderne p\xe5 en given dag. Indl\xe6gget beskriver, at South Pole Station f\xf8lger New Zealands tid, og indeholder andre data s\xe5som skumringsstadier og s\xe6sonens f\xf8rste stjerneobservation.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nEt indl\xe6g i Hacker News viser smukke fotos af solnedgang f\xf8r en 6-m\xe5neders polarnat. Kommentarerne omhandler h\xe5ndtering af manglende sollys, regulering af lys og konstruktion af videnskabelige faciliteter. Solargraphy eksperiment mislykkedes. Opf\xf8relsen af anl\xe6g p\xe5 Sydpolen er imponerende. Diskussion om de bizarre f\xe6nomener ved solens cirkul\xe6re rejse og dens indvirkning p\xe5 levevilk\xe5rene. Antarktis er ug\xe6stfrit og man m\xe5 konkurrere om en position for at se solens op- og nedgang. Kommentatorer diskuterer ogs\xe5 udfordringerne med at tr\xe6kke vejret i ekstrem kulde. Artiklen giver et interessant perspektiv p\xe5 livet og forskningen i Antarktis."]}),"\n",(0,t.jsx)(r.h2,{id:"hollandsk-journalist-der-skriver-kritisk-om-kina-er-m\xe5l-for-intimideringsplan",children:"Hollandsk journalist, der skriver kritisk om Kina, er m\xe5l for intimideringsplan"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Original"}),".\nMarije Vlaskamp, en hollandsk journalist, der er kritisk over for Kina, har siden sidste efter\xe5r v\xe6ret udsat for en bizar intimideringsplan, der har omfattet bombetrusler og meddelelser med krav om, at hun skulle tr\xe6kke en artikel tilbage. Vlaskamp har tidligere skrevet kritisk om den kinesiske stat med fokus p\xe5 undertrykkelsen af uighurerne og kinesiske dissidenter i Nederlandene. Den kinesiske ambassade i Haag har v\xe6ret udsat for en bombetrussel, hvori b\xe5de Vlaskamp og Wang Jingyu, som er et af emnerne i hendes artikler, blev n\xe6vnt. Mens Vlaskamps gerningsm\xe6nd ikke fors\xf8ger at skjule truslens kinesiske oprindelse, har den kinesiske ambassade n\xe6gtet at v\xe6re involveret i at opmuntre angriberne."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),'.\nEn hollandsk journalist er m\xe5l for en intimideringsplan; Discussion Service-brugere diskuterer kinesisk indblanding og opfordrer regeringerne til at g\xf8re mere. Kinesiske politistationer opererer i Holland og andre lande, og landene kan blive n\xf8dt til selv at unders\xf8ge s\xe5kaldte "gr\xe5 aktioner". Kritikere h\xe6vder, at Kinas handlinger kr\xe6nker suver\xe6niteten, og nogle politikere er blevet truet som f\xf8lge heraf. Discussion Service-brugere diskuterer Kinas rolle i de seneste bombetrusler mod dissidente journalister, der bor i USA; debatter om Kinas regering og dens handlinger over for vestlige journalister. ASML, en hollandsk virksomhed, optr\xe6der i en sammenh\xe6ng, hvor Kina sigter mod at eje Vestens elektronik.']}),"\n",(0,t.jsx)(r.h2,{id:"usps-anl\xe6g-i-utah-g\xf8r-intet-andet-end-at-tyde-h\xe5ndskrift",children:"USPS-anl\xe6g i Utah g\xf8r intet andet end at tyde h\xe5ndskrift"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Original"}),".\nUSPS-anl\xe6gget i Utah har specialiseret sig i at afkode rodede h\xe5ndskrifter p\xe5 post. Dette anl\xe6g besk\xe6ftiger over 90 personer, som sorterer posten og bruger avanceret teknologi til at behandle den. Den anvendte teknologi kan endda scanne og digitalisere h\xe5ndskrevne adresser. Anl\xe6gget viser, hvordan teknologien udvikler sig til at h\xe5ndtere traditionelle opgaver p\xe5 innovative m\xe5der."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nUSPS-anl\xe6gget i Utah har specialiseret sig i at afkode kursiv h\xe5ndskrift med en software leveret af Eagle og Siemens. H\xe5ndskriftgenkendelse har v\xe6ret en udfordring for postarbejderne, og der er stadig behov for menneskelig indgriben. Diskussionen p\xe5 Hacker News ber\xf8rer udviklingen af arbejdskraft og l\xf8nninger, ejendomsret, statstilskud og fordelene ved at skrive i b\xf8ger. Salt Lake Citys mormonsamfund menes at have bidraget til facilitetens store antal dygtige l\xe6sere. Nogle foresl\xe5r, at USPS b\xf8r oprette en mobilapp, mens andre udtrykker bekymring for kr\xe6nkelser af privatlivets fred med brugen af private data."]}),"\n",(0,t.jsx)(r.h2,{id:"apple-forts\xe6tter-bestr\xe6belserne-p\xe5-at-forhindre-detailbutikker-i-at-blive-fagforenet",children:"Apple forts\xe6tter bestr\xe6belserne p\xe5 at forhindre detailbutikker i at blive fagforenet"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Original"}),".\nApple fors\xf8ger at forhindre, at dets detailbutikker bliver fagforeninger, samtidig med at Apple diversificerer sin produkt- og komponentproduktion uden for Kina. Virksomheden har for nylig oplevet afskedigelser af arbejdspladser og endnu en ledelsesafgang. Artiklen n\xe6vner ogs\xe5 den kommende udgivelse af Apples mixed-reality headset."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple beskyldes for fagforeningsfjendtlig taktik, herunder tilbageholdelse af ydelser; kritik af fagforeningens forhandlingstaktik. Diskussion om kompleksiteten ved fagforening og arbejdstagerens indflydelse. Gallupunders\xf8gelse viser stigende interesse for fagforening, is\xe6r blandt frontmedarbejdere. Nogle kritiserer den lave l\xf8n og de manglende fordele ved detailhandelsjobs, mens andre h\xe6vder, at forfremmelser og afskedigelser p\xe5 grundlag af anciennitet kan have en negativ indvirkning p\xe5 virksomhederne."]}),"\n",(0,t.jsx)(r.h2,{id:"plrust-10-nu-et-p\xe5lideligt-sprog-til-postgres",children:"PL/Rust 1.0: nu et p\xe5lideligt sprog til Postgres"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Original"}),".\nPL/Rust er et indl\xe6sbart proceduresprog, der g\xf8r det muligt at skrive PostgreSQL-funktioner i Rust, hvilket giver adgang til Postgres' Server Programming Interface og sikre Rust-typer frem for de fleste af Postgres' indbyggede datatyper; PL/Rust-funktioner kompileres til indf\xf8dt maskinkode i stedet for at blive fortolket, hvilket giver den bedste ydeevne. PL/Rust er nu et betroet proceduralsprog for Postgres p\xe5 x86_64- og aarch64-systemer, hvis de rette kompileringskrav er opfyldt, hvilket g\xf8r det muligt for PL/Rust at leve i et univers af Safe Rust; PL/Rust bruger sin egen rustc-driver til at anvende tilpassede lints til en brugers LANGUAGE plrust-funktion for at anvende visse kodeidiomer, som de ved ikke har \"I-Unsound\"-problemer. Som standard udf\xf8rer PL/Rust ikke krydskompilering, men det skal installeres og aktiveres via konfigurationen."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 har nu tillid til Postgres som et alternativ til databasefunktioner. Cloud-udbydere RDS og Supabase muligg\xf8r PL/Rust-implementering. Har exceptionel ydeevne, men er stadig s\xe5rbar over for problemer. Event triggers og DO-blokke er endnu ikke blevet indarbejdet. Rust har adgang til dev-\xf8kosystem, effektive typer og bedre ydeevne. Kan begr\xe6nse optimering for beregningsm\xe6ssige triggers."]}),"\n",(0,t.jsx)(r.h2,{id:"twitter-blokerer-likes-og-retweets-der-n\xe6vner-substack",children:"Twitter blokerer likes og retweets, der n\xe6vner Substack"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),".\nTwitter blokerer likes/retweets, der n\xe6vner Substack, hvilket for\xe5rsager Streisand-effekt. Elon Musk beskylder Substack for at skrabe Twitter-database, eksperter finder udsagnet meningsl\xf8st. Substack ben\xe6gter uretm\xe6ssig brug af Twitter API'er. Kritik af Twitter's s\xf8geresultater, forbud og API-brugspolitik. Bekymringer over kvaliteten af Substack newsfeed-funktionen. Konkurrerende Twitter og Substack udvikler sig, alternative mikrobloggingprotokoller unders\xf8ges. Modstand mod at g\xf8re problemet til et skuespil, opfordring til ansvarlighed fra ledelsens side. Fortsat debat om API-misbrug og Substacks p\xe5st\xe5ede scraping af Twitter-indhold. Advarsel mod at afvise de afskedigede Substack-medarbejderes situation."]}),"\n",(0,t.jsx)(r.h2,{id:"z-library-vil-lade-brugerne-dele-fysiske-b\xf8ger",children:"Z-Library vil lade brugerne dele fysiske b\xf8ger"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Original"}),'.\nZ-Library, det st\xf8rste lager af piratkopierede b\xf8ger, udvider sine tjenester til ogs\xe5 at omfatte et marked for fysisk bogdeling, hvor millioner af brugere kan hente paperbacks p\xe5 s\xe6rlige "Z-points" rundt om i verden. Det er planen at organisere "indsamlings- og opbevaringssteder" for b\xf8ger, som "vil v\xe6re forbindelsen mellem dem, der deler deres b\xf8ger, og dem, der har brug for dem", hvilket vil kr\xe6ve betydelig lagerplads og organisatorisk indsats, s\xe5 opfyldelsescentre og logistiktjenester fra tredjeparter er velkomne. En meddelelse, der er offentliggjort p\xe5 webstedet, ser ud til at v\xe6re seri\xf8s, idet folk foresl\xe5r Vietnam, Brasilien, Portugal, Colombia, Iran, Usbekistan, Nigeria, Spanien, Indien, Argentina, Egypten, Frankrig, Etiopien, Kina og Ghana som ideelle Z-Point-lokationer, og webstedet modtager i \xf8jeblikket gerne feedback for at forbedre sin service.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library vil give brugerne mulighed for at dele fysiske b\xf8ger, men forlagene kan sags\xf8ge biblioteket; nogle foresl\xe5r at scanne b\xf8ger, \xe6ndre ophavsretslove eller give incitamenter til at scanne b\xf8ger. Nogle diskuterer gennemf\xf8rligheden og virkningerne for forlagene af at lancere et marked for bogdeling i den virkelige verden. Licensmodeller for e-b\xf8ger har uheldige konsekvenser, der f\xf8rer til piratkopiering som en form for protest. Private medlemsbiblioteker var tidligere end folkebibliotekerne og blev ofte udl\xe5nt."]}),"\n",(0,t.jsx)(r.h2,{id:"perseus---nextjs-alternativ-i-rust",children:"Perseus - NextJS-alternativ i Rust"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Original"}),".\nPerseus er et Rust-rammev\xe6rk til moderne webapps, der genererer tilstand on-demand og videregiver den til Sycamore, med Fluent-baseret I18n tilf\xf8jet for flersproget funktionalitet, plugins til tilpasning, alt i WebAssembly for h\xf8j ydeevne, og eksporterbar/statisk serveret, let at installere og brugervenlig."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nBrugere diskuterer Perseus, et Rust-baseret alternativ til NextJS, hvor nogle foretr\xe6kker JS til front-end udvikling p\xe5 grund af Rusts v\xe6rkt\xf8j. P\xe5 trods af dette tyder Rusts indtog i de lavere niveauer af JS stakken p\xe5 et potentiale i inkorporeringen af JS/TS i Rust frameworks som Perseus. Der opst\xe5r diskussioner om Rusts fordele i forhold til Go, idet nogle brugere ser Rust som mere egnet til programmering p\xe5 lavt niveau, mens andre ser Go som bedre egnet til webudvikling. V\xe6rdien af et programmeringssprog afh\xe6nger af, hvor man bor og \xf8nsker at arbejde. Udgivelsen af Perseus fanger teknisk kyndige personers opm\xe6rksomhed som et muligt hurtigere alternativ til Svelte, men m\xf8der kritik for at v\xe6re sv\xe6rt at bruge i den virkelige verden."]}),"\n",(0,t.jsx)(r.h2,{id:"en-baby-gpt",children:"En baby GPT"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nEn Discussion Service-bruger foresl\xe5r at bruge bin\xe6re regul\xe6re udtryk til sproglige relationer, mens en anden bruger argumenterer for betydning og hensigt. Skaberen af baby GPT sammenligner med Markov-k\xe6de. Ekspert anbefaler bedre matematiske v\xe6rkt\xf8jer. Discussion Service-bruger sp\xf8rger om konsekvenserne for den brede offentlighed. Ingen bem\xe6rkelsesv\xe6rdig ny teknologi eller udgivelse."]}),"\n",(0,t.jsx)(r.h2,{id:"to-typer-af-softwareingeni\xf8rer",children:"To typer af softwareingeni\xf8rer"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Original"}),".\nArtiklen omhandler to typer softwareingeni\xf8rer: Type 1, som antager, at et problem er let, hvis det ikke er teknisk, og Type 2, som antager, at det er sv\xe6rt, fordi det involverer mennesker. Type 1 tror p\xe5 Engineering med stort E, mens type 2 fokuserer p\xe5 mennesker og ser tekniske problemer som involverende mennesker. Mens type 1 er mere almindelig, forst\xe5r type 2-ingeni\xf8rer, at ingeni\xf8rarbejde indeb\xe6rer kaos og kompleksitet og sigter mod at bygge p\xe5 trods af disse udfordringer. Artiklen indeholder nogle eksempler til illustration af forskellene, men forfatteren har endnu ikke defineret eller trukket gr\xe6nsen mellem de to typer pr\xe6cist."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nEn diskussion om to typer softwareingeni\xf8rer, herunder type 3, og om vigtigheden af at forst\xe5 produktstyring. Debat om balancen mellem innovation og stabilitet og om behovet for ordentlig dokumentation. Dikotomi mellem at stole p\xe5 mennesker og at implementere automatiserede l\xf8sninger inden for software engineering. Vigtigheden af at tilpasse alle til f\xe6lles m\xe5l og forst\xe5 st\xf8rre forretningsbehov. Der s\xe6ttes sp\xf8rgsm\xe5lstegn ved kategoriseringen af softwareingeni\xf8rer, med v\xe6gt p\xe5 at finde den grundl\xe6ggende \xe5rsag til problemer. Indl\xe6gget giver stof til eftertanke."]}),"\n",(0,t.jsx)(r.h2,{id:"avanceret-linux-programmering-2001",children:"Avanceret Linux-programmering (2001)"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Original"}),".\n'Advanced Linux Programming' af CodeSourceryLLC er en bog, der hj\xe6lper GNU/Linux-udviklere med at skabe software med brugervenlige funktioner, avancerede muligheder s\xe5som multi-threading, interprocesskommunikation og interaktion med hardwareenheder samt generel programforbedring. Desuden l\xe6rer denne bog udviklerne at arbejde i GNU/Linux-systemets milj\xf8, herunder dets unikke begr\xe6nsninger, konventioner og muligheder. Denne bog kan downloades under Open Publication License, version 1, og kommer med adgang til kodekpr\xf8ver omfattet af GNU General Public License-koden. Errata og overs\xe6ttelser af bogen er tilg\xe6ngelige."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),'.\nHacker News-brugere diskuterer relevansen af 2001-bogen "Advanced Linux Programming" i 2021. Nogle brugere foresl\xe5r, at for\xe6ldede afsnit opdateres. Selv om det er en bog for begyndere, er den stadig en nyttig ressource til Linux API-udvikling. Aria2 download-applikation tjener som et alternativ til serverhastighedslofter.']}),"\n",(0,t.jsx)(r.h2,{id:"et-cern-for-open-source-large-scale-ai",children:"Et CERN for Open Source Large-Scale AI"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Original"}),".\nLAION e.V. har lanceret en underskriftsindsamling om et internationalt, offentligt finansieret supercomputerforskningsanl\xe6g for AI med \xe5ben kildekode i lighed med CERN for at demokratisere AI-forskning og fremme forskning i sikkerhed og sikring. Platformen openPetition har til form\xe5l at styrke borgernes deltagelse og st\xf8tte andragender om forandring. Initiativet har til form\xe5l at beskytte demokratiske principper mod at blive undermineret af nogle f\xe5 udvalgte store virksomheder. En Discussion Service-bruger bem\xe6rkede, at 19 % af st\xf8tterne kommer fra laion.ai, mens 64 % forbliver ukendte. Borgerne opfordres til at donere for at st\xf8tte underskriftsindsamlingen, der har vundet indpas p\xe5 Hacker News."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nEn artikel p\xe5 openpetition.eu fremh\xe6ver Europas behov for et CERN-lignende open source-initiativ til fremme af samarbejdet mellem AI-forskere, akademikere og iv\xe6rks\xe6ttere. Samarbejde er n\xf8dvendigt for at kunne udf\xf8re big data processing med store kapitalinvesteringer. Open source-projekter er n\xf8dvendige for at fastholde AI-forskere og gavne samfundet snarere end virksomheders aktion\xe6rer. CERN's succes g\xf8r det til en attraktiv model, selv om nogle mener, at markedet giver tilstr\xe6kkelige incitamenter. AI's tv\xe6rfaglige karakter kr\xe6ver, at der tages hensyn til indbyrdes forbundne sp\xf8rgsm\xe5l."]}),"\n",(0,t.jsx)(r.h2,{id:"permafrost-motor---en-opengl-rts-spilmotor-skrevet-i-c",children:"Permafrost-motor - en OpenGL RTS-spilmotor skrevet i C"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Original"}),".\nPermafrost Engine er en OpenGL 3.3 Real Time Strategy spilmotor skrevet i C, lavet i billedet af gamle klassikere, men med indarbejdelse af nogle moderne ideer. EVERGLORY er det flagskibsspil, der er udviklet med Permafrost Engine, og som viser motorens muligheder med f\xf8rsteh\xe5ndserfaring fra spillet. Motorresumeet indeholder en liste over OpenGL- og Python-funktioner, RTS-mekanik og cross-platform-muligheder. Licensen for Permafrost Engine er GPLv3, med en s\xe6rlig undtagelse for linking. Der findes byggevejledninger til b\xe5de Linux og Windows. En devlog og en e-mail til sp\xf8rgsm\xe5l/kommentarer vedr\xf8rende projektet eller kildekoden er til r\xe5dighed for interesserede brugere."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nOpen-source Permafrost-motoren f\xe5r opm\xe6rksomhed p\xe5 Discussion Service til et nyt open-source RTS-spil. Everglory-spillets skrifttypernes klarhed kritiseres. Sammenligning \xf8nskes med andre RTS-motorer. Udviklernes test p\xe5 h\xe5ndholdte sk\xe6rme er vigtig. H\xe5b om genoplivning af RTS-genren. Brugere diskuterer open source RTS-motorer og anvendte sprog. Omtale af en anden open source Frostbite engine implementering."]}),"\n",(0,t.jsx)(r.h2,{id:"lukning-af-en-for\xe6ldet-ssh-forbindelse",children:"Lukning af en for\xe6ldet SSH-forbindelse"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Original"}),".\nIndl\xe6gget diskuterer, hvordan man lukker en for\xe6ldet SSH-session, og angiver, at selv om den f\xf8rste l\xf8sning kan v\xe6re at lukke terminalemulatoren, er der en bedre m\xe5de at lukke den p\xe5 ved hj\xe6lp af de indbyggede SSH-emulatorer. Indl\xe6gget forklarer, hvordan tilde-pr\xe6fikset (",(0,t.jsx)(r.del,{children:') efterfulgt af en kommando kan udl\xf8se flere skjulte kommandoer i SSH-klienter, herunder kommandoen "terminate session" ('}),'.). Indl\xe6gget bem\xe6rker, at man skal v\xe6re opm\xe6rksom p\xe5, at der kr\xe6ves en forudg\xe5ende newline, og tilbyder en lille note til folk, der bruger et tastatur med nordisk layout til at skrive tilde-tegnet. Indl\xe6gget slutter med en diskussion af, hvad man skal g\xf8re efter at have brugt flugtsekvensen "terminate session".']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nEn Discussion Service-bruger giver et SSH-tip. En anden g\xf8r opm\xe6rksom p\xe5 et layoutproblem, men giver en l\xf8sning. Der foresl\xe5s en konfiguration af EscapeChar. Diskussion om SSH manpage, jumping hosts og SSH-forbindelser. Sticky SSH-session \xf8nskes. Autossh anbefales til auto-attach, og Mosh til \xe6ndring af port forwarding. Krypteringsdetaljer og yderligere tips gives. Advarsel mod at bruge Alpine Linux."]}),"\n",(0,t.jsx)(r.h2,{id:"flatcar-container-linux",children:"Flatcar Container Linux"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.flatcar.org/",children:"Original"}),".\nFlatcar Container Linux er en f\xe6llesskabs Linux-distribution, der er designet til containerarbejdsbelastninger med h\xf8j sikkerhed og lav vedligeholdelse. OS-imaget indeholder kun de v\xe6rkt\xf8jer, der er n\xf8dvendige for at k\xf8re containere uden pakkeh\xe5ndtering eller konfigurationsdrift. Det uforanderlige filsystem og automatiserede atomare opdateringer giver et st\xe6rkt fundament for infrastruktursikkerhed. Flatcar Container Linux' indbyggede sikkerhedsfunktioner og den reducerede angrebsoverflade forenkler styresystemets administration. Den indeholder v\xe6rkt\xf8jer til at administrere infrastrukturer i stor skala og underst\xf8tter globale initiativer. Automatiserede, atomare opdateringer sikrer, at du k\xf8rer den mest stabile, sikre og opdaterede Flatcar-version. Det er en drop-in erstatning for CoreOS Container Linux."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nMicrosofts Flatcar Container Linux opdatering og forts\xe6tter efter overtagelsen, hvilket giver et alternativ til CloudInit. Den uforanderlige infrastrukturtilgang vinder popularitet p\xe5 trods af Ignitions tekniske problemer. Flatcar Linux-udviklere foresl\xe5r en venlig opdatering. Discussion Service-brugere diskuterer tilf\xf8jelse af containere og foresl\xe5r en UEFI-firmware for at opn\xe5 bedre ydeevne."]}),"\n",(0,t.jsx)(r.h2,{id:"microsoft--jarvis-et-system-til-at-forbinde-llmer-med-ml-f\xe6llesskabet",children:"Microsoft / JARVIS: et system til at forbinde LLM'er med ML-f\xe6llesskabet"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://github.com/microsoft/JARVIS",children:"Original"}),".\nMicrosoft og Hugging Face har afsl\xf8ret laboratorieprojektet JARVIS, en AI-assistent til at forbinde sprog- og maskinl\xe6ringsmodeller. JARVIS bruger en stor sprogmodel (LLM) til at forst\xe5 og analysere anmodninger og bruger derefter et udvalg af mange ekspertmodeller til at udf\xf8re den \xf8nskede opgave. Den best\xe5r af fire faser: planl\xe6gning af opgaver, udv\xe6lgelse af modeller, udf\xf8relse af opgaver og generering af svar. Brugeren kan f\xe5 en letv\xe6gtsoplevelse med JARVIS uden at installere modellerne lokalt ved at aktivere CLI-tilstanden eller websiden, som viser en brugervenlig gr\xe6nseflade, der kommunikerer med JARVIS."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft lancerer JARVIS for at forbinde LLM'er med ML-f\xe6llesskabet ved hj\xe6lp af regelbaserede tilgange og maskinl\xe6ring. Nogle spekulerer i, om autonome AI-agenter kan beg\xe5 svindel eller svindel, selv om l\xe6serne hovedsageligt er begejstrede. Jarvis genererer tekst og billeder baseret p\xe5 LLM's valg af modeller, men nogle giver udtryk for bet\xe6nkeligheder med hensyn til varem\xe6rkeproblemer og aflytning."]}),"\n",(0,t.jsx)(r.h2,{id:"sf\xe6risk-tokamak-opn\xe5r-afg\xf8rende-plasmatemperaturer",children:"Sf\xe6risk tokamak opn\xe5r afg\xf8rende plasmatemperaturer"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Original"}),".\nTokamak Energy's sf\xe6riske tokamak opn\xe5ede ion-temperaturer p\xe5 over 100 millioner Kelvin - et afg\xf8rende skridt i udviklingen af fusionsenergiteknologi. Den lille st\xf8rrelse, plasmastabiliteten og de magnetiske indeslutningsegenskaber ved sf\xe6riske tokamakker g\xf8r dem til et attraktivt valg til kommerciel produktion af fusionsenergi. Steven McNamara, videnskabsdirekt\xf8r hos Tokamak Energy, mener, at virksomheden kan s\xe6tte fusionsenergi p\xe5 nettet inden for 10 \xe5r og supplere andre vedvarende energikilder. I gennembruddet anvendes Thomson-spredning til at m\xe5le temperatur og massefylde p\xe5 flere punkter, hvilket baner vejen for kommercielle fusionskraftv\xe6rker, der er billige og anvendelige. Teknologien har ogs\xe5 potentielle anvendelsesmuligheder inden for b\xe6redygtig luftfart og brintbr\xe6ndstofproduktion."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nEn sf\xe6risk tokamak opn\xe5r afg\xf8rende plasmatemperaturer. Nogle brugere diskuterer strukturelle sp\xf8rgsm\xe5l, og en anbefaler en podcast om fusionsenergi. I artiklen forklares behovet for en varmeveksler og de reducerede omkostninger ved det nye design. Det diskuteres, om kommerciel fusion er levedygtig. Fordobling af magnetstyrken i sm\xe5fors\xf8g g\xf8r fremskridt. Affalds- og sikkerhedsfordelene ved fusion i forhold til fission n\xe6vnes. Sf\xe6riske tokamakker er en avanceret anvendelse. Den milep\xe6l, der er n\xe5et, er endnu ikke brugbar, men der er gjort fremskridt med hensyn til magnetstyrken."]}),"\n",(0,t.jsx)(r.h2,{id:"de-f\xf8rste-p\xe5ske\xe6g-i-et-spil-var-et-opr\xf8r-fra-virksomhedernes-side",children:'De f\xf8rste "p\xe5ske\xe6g" i et spil var et opr\xf8r fra virksomhedernes side'}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Original"}),'.\nDe f\xf8rste p\xe5ske\xe6g i videospil var et resultat af, at designere blev n\xe6gtet kredit for deres arbejde, hvilket f\xf8rte til skjulte budskaber i spil. Det f\xf8rste p\xe5ske\xe6g blev fundet i Ataris spil "Adventure" fra 1980, der blev skabt af Warren Robinett. Traditionen med skjulte budskaber fortsatte i 1970\'ernes arkadespil for at s\xf8ge anerkendelse og individualitet. Robinetts p\xe5ske\xe6g l\xf8ftede hans status, og han fortsatte med at udvikle en succesfuld softwarevirksomhed. Tech Times rapporterer om forskellige cookies, der anvendes af virksomheder til at spore brugernes adf\xe6rd p\xe5 nettet og tilpasse annoncer, men de er endnu ikke blevet klassificeret.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nEt indl\xe6g i Hacker News om virksomhedsopr\xf8r gennem p\xe5ske\xe6g indeholder anekdoter og aktuelle virksomhedspolitikker. L\xe6sernes interesse kan v\xe6kke interesse p\xe5 grund af den historiske relevans og udviklingen af p\xe5ske\xe6ggets rolle. De nuv\xe6rende p\xe5ske\xe6g er udtryk for virksomhedens stolthed, ikke for ulydighed. Kodeksgennemgang forhindrer p\xe5ske\xe6g. Tidligere teknologivirksomheder falder ofte under nyudn\xe6vnte MBA'er. Warren Robinett roses for Adventure game. U2's medlem og Atari-fan har forskellige navne."]}),"\n",(0,t.jsx)(r.h2,{id:"modular-fejl-i-rust",children:"Modular Fejl i Rust"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://sabrinajewson.org/blog/errors",children:"Original"}),".\nArtiklen diskuterer vigtigheden af modul\xe6r fejlh\xe5ndtering og introducerer princippet om at fejltyper skal v\xe6re t\xe6t p\xe5 deres fejlenhed, med et hypotetisk Rust-bibliotek som eksempel. Problemer med ubehj\xe6lpsomme fejlmeddelelser, manglende udvidelsesmuligheder og vanskeligheder med at matche fejl skitseres, og der foresl\xe5s l\xf8sninger s\xe5som .source()-metoden og en bedre konstruktion af fejltyper. Eksempelbibliotekets fejltype opdeles i tre forskellige typer med gode backtraces og pr\xe6cis fejlmatchning, og I/O-fejl forklares ved hj\xe6lp af en mere struktureret fejltypekonstruktion. Artiklen fremh\xe6ver betydningen af gode backtraces, udvidelighed, inspicerbarhed, stabilitet og modularitet i fejlh\xe5ndtering og foresl\xe5r, at god fejlh\xe5ndtering er v\xe6rd at l\xe6re."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nRusts fejlmeddelelser er popul\xe6re, men der er behov for varierede fejltyper. SNAFU giver mulighed for at producere unikke spor. Distinkte fejl reducerer spredning og g\xf8r h\xe5ndteringen lettere, men pas p\xe5 med at underst\xf8tte offentlige API'er. Logning og afslutning b\xf8r ikke v\xe6re den prim\xe6re fremgangsm\xe5de til fejlfinding af biblioteker. Granul\xe6re eller uigennemsigtige fejl med beskrivelser er at foretr\xe6kke. Kontrollerede undtagelser i Java er prisv\xe6rdige. Den fatale fejl ved Java er, at der ikke findes algebraiske typer."]}),"\n",(0,t.jsx)(r.h2,{id:"68-95-997-regel",children:"68-95-99.7 Regel"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\n68-95-99,7-reglen er en statistisk tiln\xe6rmelse, der estimerer procentdelen af v\xe6rdier inden for en standardafvigelse fra middelv\xe6rdien i en normalfordeling. Reglen siger, at ca. 68 %, 95 % og 99,7 % ligger inden for henholdsvis en, to og tre standardafvigelser. Denne regel har flere anvendelsesmuligheder inden for forskellige omr\xe5der, f.eks. kvalitetskontrol og dataanalyse. Det er en hurtig m\xe5de at f\xe5 et groft sandsynlighedsestimat for en population, der antages at v\xe6re normal. Formlen kan anvendes p\xe5 forskellige fordelinger, og den kan hj\xe6lpe med at identificere outliers i dataanalyser."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nDiscussion Service-kommentarer diskuterer begr\xe6nsningerne ved 68-95-99,7-reglen i forbindelse med analyse af data. Nassim Nicholas Talebs arbejde og Chebyshevs ulighed n\xe6vnes. Tangenter om finansiel handel og det amerikanske optionsmarkeds historie. Ekspertbrugere h\xe6vder, at h\xf8je IQ-scoringer er up\xe5lidelige og at skalaen er arbitr\xe6r."]}),"\n",(0,t.jsx)(r.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Original"}),".\nUnicodePlots-biblioteket er et plottingv\xe6rkt\xf8j p\xe5 h\xf8jt niveau til brug i Julias REPL, som omfatter spredningsdiagrammer, linjediagrammer og varmekort. Det underst\xf8tter ogs\xe5 fysiske st\xf8rrelser fra Unitful.jl og intervaller fra IntervalSets.jl, giver mulighed for tilpasning af plotfunktioner som ploth\xf8jde og -bredde og omvendte/vendte plotakser og underst\xf8tter lagring af plots som PNG eller TXT."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nJulia-baserede UnicodePlots viser diagrammer og histogrammer p\xe5 terminalen til hurtig visualisering p\xe5 fjernservere. Det svarer til et behov for hurtig datavisualisering i terminalen uden at installere en fuld grafikstack. UnicodePlots er for det meste kopieret i en Ruby-port, og en Python-version, der er kompatibel med Matplotlib. Der er i \xf8jeblikket en tendens til tekstbrugergr\xe6nseflader, hvilket skaber en opdeling mellem Electron til slutbrugerapps og TUI til b\xe6rbare v\xe6rkt\xf8jer. Den har 100 % koded\xe6kning, underst\xf8tter sammenlignende histogrammer og giver brugerne mulighed for at kopiere og inds\xe6tte data direkte i kommentarer eller beskrivelser. Selv om UnicodePlots ikke er en helt ny teknologi, er det et nyttigt v\xe6rkt\xf8j for dem, der har brug for hurtigt at vurdere data."]}),"\n",(0,t.jsx)(r.h2,{id:"digitale-samlerobjekter-p\xe5-instagram-er-ved-at-blive-afviklet",children:"Digitale samlerobjekter p\xe5 Instagram er ved at blive afviklet"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nFra den 11. april 2023 vil Instagram afvikle sin underst\xf8ttelse af digitale samlerobjekter, hvilket p\xe5virker oprettelsen af nye indl\xe6g med digitale samlerobjekter, synligheden af digitale tegneb\xf8ger og tilg\xe6ngeligheden af blockchain-informationer. Sletningen af data om digitale samlerobjekter vil ske i overensstemmelse med Instagrams privatlivspolitik og brugsbetingelser for digitale samlerobjekter, men brugerne kan indsende en anmodning om at hente deres oplysninger inden fristen. Indholdet af tredjeparters digitale tegneb\xf8ger vil ikke blive p\xe5virket."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),".\nInstagrams digitale samlerobjekter er ved at miste fart, men web3-troende er ikke afskr\xe6kket. NFT-omr\xe5det er n\xf8dt til at tage fat p\xe5 ejerskabsstandarder og forretningsadoption. Reddits avatarer s\xe6lger godt, selv om polygon-NFT'er opfattes som mindre v\xe6rdifulde. Vinteren er velkommen for bygherrer til at opbygge infrastruktur og for traditionelle virksomheder til at l\xe6re om decentrale netv\xe6rk. Succesen med Pokemon-kort og Reddit-funktioner sammenlignes med begrebet knaphed. Udtrykket \"Web3\" er m\xe5ske for tidligt, og svindlere og bygherrer befinder sig i forskellige lejre. Der er skepsis og bekymring over NFT-hype, investeringsrisici og mental sundhed. Der diskuteres kultinddragelse i brancher, krypto og AI-risici. ChatGPT's nyttev\xe6rdi debatteres, og brugerne fokuserer p\xe5 friske indsigter uden politisk eller religi\xf8st sprog. Konteksten for avanceret teknologi i forbindelse med kommunikation og jordsynkronisering diskuteres, med varierende meninger om NFT-v\xe6rdi og dens indvirkning p\xe5 samfundet."]}),"\n",(0,t.jsx)(r.h2,{id:"den-afg\xf8relse-der-truer-bibliotekernes-fremtid",children:"Den afg\xf8relse, der truer bibliotekernes fremtid"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"Original"}),'.\nEn afg\xf8relse fra en forbundsdomstol om, at kontrolleret digital udl\xe5n (CDL) er i strid med ophavsretsloven, kan f\xe5 katastrofale konsekvenser for bibliotekerne, herunder at de skal v\xe6lge mellem at k\xf8be dyre e-bogslicenser fra forlagene eller udvide deres samlinger; Internet Archive (IA), en nonprofitorganisation, der udl\xe5ner digitale kopier af de millioner af b\xf8ger, som den har indsamlet og digitaliseret, har v\xe6ret i centrum for en retssag fra flere bogforlag, som i 2020 sags\xf8gte den med p\xe5stand om kr\xe6nkelse af ophavsretten; og det var denne CDL-udl\xe5nsmodel, som domstolen afviste i sidste m\xe5ned, og som kunne have "uretf\xe6rdig magt over b\xe5de b\xf8gernes og bibliotekernes fremtid", if\xf8lge advokat Corynne McSherry fra Electronic Frontier Foundation, som repr\xe6senterer IA i dens appel af dommen.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nEn domstolsafg\xf8relse om kontrolleret digital udl\xe5n og ophavsretslove har udl\xf8st debatter, med forslag om at forkorte ophavsrettens l\xe6ngde for at forhindre tab af viden; nogle foresl\xe5r, at forlagenes fortjeneste ikke b\xf8r v\xe6re et sp\xf8rgsm\xe5l om udl\xe5n af CDL-materiale. Biblioteker har tilpasset sig til at blive offentlige underholdningscentre, og offentlighedens adgang til ressourcer er afg\xf8rende; bibliotekarer bruger ekspertudtalelser til at afveje udl\xe5nspopularitet, bogv\xe6rdi og bibliotekets mission, n\xe5r de kasserer b\xf8ger. Forl\xe6ggernes retssager mod Internet Archive's ubegr\xe6nsede royaltyfri digitale distribution bringer forfatternes indtjening i fare, og kontrolleret digital udl\xe5n kan bringe beskyttelsen af ophavsretslovgivningen i fare. Krydsfeltet mellem digitalt og fysisk ejerskab er fortsat et debatemne; diskussionerne giver unikke perspektiver p\xe5 det aktuelle sp\xf8rgsm\xe5l."]}),"\n",(0,t.jsx)(r.h2,{id:"do-kwon-konverterede-ulovlige-midler-fra-luna-til-bitcoin",children:"Do Kwon konverterede ulovlige midler fra LUNA til Bitcoin"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Original"}),".\nSydkoreanske anklagere har identificeret ulovlige aktiver til en v\xe6rdi af n\xe6sten 314,2 millioner dollars, der er knyttet til Terraform Labs' medstifter, Do Kwon, og hans medarbejdere, hvoraf Kwon alene er forbundet med omkring 69 millioner dollars. Anklagemyndigheden har kontaktet Binance for at standse enhver anmodning om tilbagetr\xe6kning, der er forbundet med Kwon. Kwon har angiveligt konverteret de fleste af de ulovlige midler, som udg\xf8r omkring 414,5 milliarder won, til Bitcoin, og ingen af de aktiver, der er knyttet til ham, kan inddrives eller er under de sydkoreanske myndigheders jurisdiktion. Terra var et krypto-\xf8kosystem, der kollapsede i maj 2022, hvor den tidligere administrerende direkt\xf8r Kwon blev anklaget for at sifonere Bitcoin til en v\xe6rdi af n\xe6sten 100 millioner dollars efter kollapset."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nOn-chain-data viser Terraform Labs' Do Kwons Bitcoin-konvertering af svigagtige LUNA-midler. Afsl\xf8rer begr\xe6nsninger i sporing af svig gennem traditionelle banker. Discussion Service-brugere diskuterer v\xe6rkt\xf8jer til beskyttelse af privatlivets fred og \xe6rlighed i krypto-omr\xe5det. Debat om, hvorvidt intelligens udviklede sig til konkurrence eller samarbejde, med nogle argumenterer for det sidste. Konkurrence og rovdrift driver konkurrence, men den overordnede tendens er at forts\xe6tte med at debattere rollerne i intelligensens udvikling."]}),"\n",(0,t.jsx)(r.h2,{id:"interview-med-andrew-kelley-zig-creator-2021",children:"Interview med Andrew Kelley (Zig Creator) (2021)"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Original"}),".\nAndrew Kelley diskuterer sine erfaringer med at udvikle programmeringssproget Zig, udfordringerne ved at balancere et fuldtidsjob med open source-arbejde, vigtigheden af at forhandle om ejerskab af intellektuel ejendom og de moralske sp\xf8rgsm\xe5l omkring kommerciel forking i open source-f\xe6llesskabet. Zig er et non-profit programmeringssprog, der har til form\xe5l at forbedre hukommelsessikkerheden og reducere informationsoverbelastningen for brugerne. Kelley forestiller sig, at Zig bliver det foretrukne sprog til styresystemer og l\xe6reb\xf8ger, hvilket vil f\xf8re til bedre programydelse, hukommelsesforbrug og stabilitet. Tech Times rapporterer ogs\xe5 om forskellige programmeringsfokuserede videokurser, der er tilg\xe6ngelige online."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nCorecursive's interview med Zig-skaber Andrew Kelley inspirerer lytterne til at downloade alle tidligere podcasts p\xe5 webstedet og diskuterer crowd funding-projekter og personlige r\xe5d i separate kommentarer. En lytter s\xe6tter pris p\xe5 den venlige atmosf\xe6re p\xe5 kanalen #chicken scheme channel. En anden fremh\xe6ver Andrew Kelleys gennemsigtighed i en forked Zig-h\xe6ndelse, men en bruger reagerer negativt p\xe5 deres interaktion med Kelley. Overordnet set nyder lytterne interviewets d\xe6kning af Zig og SQLites teknologiske historie."]}),"\n",(0,t.jsx)(r.h2,{id:"supavisor---en-postgres-connection-pooler-skrevet-i-elixir",children:"Supavisor - en Postgres connection pooler skrevet i Elixir"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://github.com/supabase/supavisor",children:"Original"}),".\nSupavisor er en Postgres-forbindelsespooler, der kan proxy millioner af Postgres-slutklientforbindelser til en tilstandspool af native Postgres-databaseforbindelser via en skalerbar, cloud-nativ arkitektur. Dette system forenkler Postgres-klyngeh\xe5ndteringen for databaseadministratorer ved at give nem konfiguration af Postgres-klynger med h\xf8j tilg\xe6ngelighed, samtidig med at det er ressourceeffektivt, skalerbart, multi-tenant og cloud-nativt. Der er allerede benchmarks og belastningstests tilg\xe6ngelige, som viser, at det kan h\xe5ndtere en million Postgres-forbindelser p\xe5 en klynge, og det kan absorbere millioner af forbindelser, hvilket g\xf8r det til et godt valg for udviklere, der forbinder til Postgres fra Serverless-milj\xf8er. Det fremtidige arbejde omfatter load balancing, session pooling, Postgres h\xf8jtilg\xe6ngelighedsstyring og API'er som Postgres binary, HTTPS og meget mere. Jos\xe9 Valim og Dashbit-holdet hjalp med at informere Supavisor-designbeslutningerne, og det er inspireret af produkter som PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy og meget mere."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nSupabase CEO introducerer Supavisor, en Postgres connection pooler bygget med Elixir, og fremh\xe6ver dens lighed med Pgbouncer og designet til multi-tenancy. Supavisors benchmarks viser, at den kan h\xe5ndtere et h\xf8jt genneml\xf8b, mens den bruger 7,8 g RAM og ~50 % CPU p\xe5 en 64vCPU-maskine. Supabase planl\xe6gger at have Supavisor foran alle sine databaser og skalere opdriften med nul nedetid. Discussion Service-brugere anmoder om tilf\xf8jelse af prepared statements i transaktionspooling-tilstand og forslag om at bruge Nimble_pool frem for Poolboy, mens de roser Elixirs underst\xf8ttelse af samtidighed og fejltolerante karakter. En Discussion Service-bruger deler arbejdserfaring med Pgbouncer p\xe5 4 vCPU-maskiner, og en anden fort\xe6ller om deres pool af f\xe6lles Pgbouncer, der rute til forskellige PostgreSQL-instanser ved hj\xe6lp af Googles Cloud SQL-proxy."]}),"\n",(0,t.jsx)(r.h2,{id:"nye-beskyldninger-om-plagiat-mod-roy-lichtenstein",children:"Nye beskyldninger om plagiat mod Roy Lichtenstein"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Original"}),'.\nDer er blevet fremsat nye beskyldninger om plagiat mod Roy Lichtenstein, idet en ny film h\xe6vder, at hundredvis af hans v\xe6rker kan spores til andre kunstnere. Dokumentarfilmen h\xe6vder, at over 30 tegneseriekunstnere blev "tilegnet" af grundl\xe6ggeren af popkunstbev\xe6gelsen, som tjente millioner p\xe5 at s\xe6lge sine v\xe6rker, mens de originale kunstnere, der blev kopieret, levede et kummerligt og endda fattigt liv. Mens nogle forsvarer Lichtensteins arbejde som "tilegnelse", kalder kritikerne det tyveri, idet der n\xe6vnes "direkte plagiater" sammen med "teknisk og kunstnerisk" overlegne v\xe6rker, som Lichtenstein har kopieret.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nNye beskyldninger om plagiat mod Roy Lichtenstein udl\xf8ser en diskussion om etik, originalitet og hensigtsm\xe6ssighed i kunstverdenen. Discussion Service-brugere diskuterer, om Lichtensteins v\xe6rk er transformativt eller \xe5benlys tyveri med minimale \xe6ndringer. Der opst\xe5r problemer med ophavsret og intellektuel ejendomsret samt sp\xf8rgsm\xe5l om den kulturelle v\xe6rdi af tegneseriekunst i forhold til fin kunst. Debatten omfatter holdninger til kunstens natur, skabelse og v\xe6rdi i kunstverdenen. De oprindelige tegneseriekunstnere blev ofte betragtet som lavt betalte varer if\xf8lge indl\xe6gget."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);